    /* (2) Analyze table cell boundaries. */
    MD_ASSERT(n_lines == 1);
    ctx->n_table_cell_boundaries = 0;
    md_analyze_marks(ctx, lines, n_lines, 0, ctx->n_marks, _T("|"), 0);
